def count_levels(filename):
    counts = {}
    with open(filename, encoding="utf-8") as f:
        for line in f:
            parts = line.split()
            if len(parts) < 3:
                continue
            level = parts[2]
            counts[level] = counts.get(level, 0) + 1
    return counts


print(count_levels("server.log"))

