from pathlib import Path

NOTES = Path("notes.txt")


def add_note(text):
    with open(NOTES, "a", encoding="utf-8") as f:
        f.write(text + "\n")


def list_notes():
    if not NOTES.exists():
        return []
    return NOTES.read_text(encoding="utf-8").splitlines()
